sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetAllHoursRulesForStore(vStore,vExpected)
	{
		function TestCase_GetAllHoursRulesForStore_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected === false)
			{
				return (vExpected === vResult);
			}
			return (vExpected == vResult.length);
		}
		
		test.TestCase(
			'Function GetAllHoursRulesForStore()',
			GetAllHoursRulesForStore,
			{
				'vStore': vStore
			},
			vExpected,
			TestCase_GetAllHoursRulesForStore_CheckResult);
	}
		
	TestCase_GetAllHoursRulesForStore(null,false);

	var grCountry = new GlideRecord('core_country');
	grCountry.initialize();
	grCountry.name = 'TEST Land';
	x_snc_devtools.GlideRecordInsert(grCountry);

	var grStore = new GlideRecord('x_snc_stores_store');
	grStore.initialize();
	grStore.name = 'TEST_ATF_1';
	grStore.country = grCountry.sys_id;
	var strStoreSysId = grStore.insert();
	
	TestCase_GetAllHoursRulesForStore(grStore,0);

	var grHoursRuleSet = new GlideRecord('x_snc_stores_hours_rule_set');
	grHoursRuleSet.initialize();
	grHoursRuleSet.store = grStore.sys_id;
	grHoursRuleSet.insert();

	TestCase_GetAllHoursRulesForStore(grStore,0);

	var grHoursRule = new GlideRecord('x_snc_stores_hours_rule');
	grHoursRule.initialize();
	grHoursRule.hours_rule_set = grHoursRuleSet.sys_id;
	grHoursRule.type = 'weekday';
	grHoursRule.weekday = 1; // Monday
	grHoursRule.start = '09:00';
	grHoursRule.end = '18:00';
	grHoursRule.insert();

	TestCase_GetAllHoursRulesForStore(grStore,1);

	var grHoursRule = new GlideRecord('x_snc_stores_hours_rule');
	grHoursRule.initialize();
	grHoursRule.hours_rule_set = grHoursRuleSet.sys_id;
	grHoursRule.type = 'weekday';
	grHoursRule.weekday = 2; // Tuesday
	grHoursRule.start = '09:00';
	grHoursRule.end = '18:00';
	grHoursRule.insert();

	TestCase_GetAllHoursRulesForStore(grStore,2);

	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
